using System.Buffers.Binary;
using System.Security.Cryptography;
using Spyro.Editor.Core.Analysis;
using Spyro.Editor.Core.Exporting;
using static Program;

internal static class TexturedBodyCases
{
    private const string Original = "fc866b2a02e010a6658f8af2de28bb3001eb33513e5924af014e35643c6dee37";
    // These OLD serialized PlanSha values were retained before this seam in
    // staging/07-source.log and body/04-source.log, not generated by new code.
    private const string OldStagingPlan = "98bd43761b87de15d2915d1377e0298ce7a0f133d2ee07c2f5672bad503af000";
    private const string OldBodyPlan = "48f1f0b4f7740c8a6277a4b440990e1fd26cb609db2153c3c24fc61d70dbbb94";
    private const string Transfer = "626ae349b98cb4bea955ac53020586f645f872225085a67bc809f46f4ab0fb07";
    private static readonly string[] OldBodies =
    [
        "b4abbdd09f794510d9b9341d7c7111ddd0b9068411bab30e70e7477b4f8c096c",
        "1314b299759ad0f66eed054db853c18e8db6dabda7c56a28cabd3fd74ea39643"
    ];
    // Independent raw-source full-body oracle, recorded before Core changes.
    private static readonly string[] NewBodies =
    [
        "347ab532881afb3975088e0872792192d8567b0abe05e7708f271741b9568cdd",
        "34d8d4c7062c0f84ef14bbbd22f66ba3ae33e68116d0877c82f4517f21622ea5"
    ];

    internal static async Task Source(string path)
    {
        RequireOriginal(path);
        var surface = await NativeId65AuthoredSurfaceBundle.CaptureAsync(path,
            new(8448, 8448, 8704, 1024, 1024, 0x708050, 0x406080));
        var companion = await NativeId65CompanionAssetPlan.CaptureAsync(path);
        var resources = await NativeId65NormalResourceBundle.CaptureAsync(path, surface, companion);
        var lists = await NativeId65ZeroSceneAnimationLists.CaptureAsync(path);
        var chain = NativeId65NormalResourceChain.Compile(resources, lists);
        NativeId65FreshSceneBundle[] fresh =
        [
            await NativeId65FreshSceneBundle.CaptureAsync(path, chain, new(8960, 8960, 9216, 64), 16),
            await NativeId65FreshSceneBundle.CaptureAsync(path, chain, new(8976, 8960, 9216, 128), 16)
        ];
        var dark = NativeStaticTerrainTextureSource.Capture(path, 14, 0);
        var gnastyWorld = NativeStaticTerrainTextureSource.Capture(path, 70, 0);
        var texture = new NativeId65FreshTerrainTexturePlan[2];
        var oldStage = new NativeId65NormalUploadStaging[2];
        var newStage = new NativeId65NormalUploadStaging[2];
        var oldBody = new NativeId65NormalBodyPlan[2];
        var newBody = new NativeId65NormalBodyPlan[2];
        byte[][] oldScene = fresh.Select(f => f.CopyScene()).ToArray();
        byte[][] oldUpload = fresh.Select(f => f.CopyUploadPayload()).ToArray();
        byte[][] oldData = fresh.Select(f => f.CopyDataComponents()).ToArray();
        byte[][] oldModel = fresh.Select(f => f.CopyModelPayload()).ToArray();
        for (int i = 0; i < 2; i++)
        {
            texture[i] = await NativeId65FreshTerrainTexturePlan.CaptureAsync(path, fresh[i], dark, gnastyWorld);
            oldStage[i] = await NativeId65NormalUploadStaging.CaptureAsync(path, fresh[i]);
            oldBody[i] = await NativeId65NormalBodyPlan.CaptureAsync(path, fresh[i], oldStage[i]);
            newStage[i] = await NativeId65NormalUploadStaging.CaptureTexturedAsync(path, texture[i]);
            newBody[i] = await NativeId65NormalBodyPlan.CaptureTexturedAsync(path, texture[i], newStage[i]);
            Check(oldStage[i].ResourceProfile == NativeId65NormalResourceProfile.UntexturedGouraudTwoTriangles &&
                oldBody[i].ResourceProfile == NativeId65NormalResourceProfile.UntexturedGouraudTwoTriangles &&
                newStage[i].ResourceProfile == NativeId65NormalResourceProfile.DirectLqTwoStaticMaterials &&
                newBody[i].ResourceProfile == NativeId65NormalResourceProfile.DirectLqTwoStaticMaterials,
                "Private actual revision, not a public constant or caller label, determines instance resource profile.");
            Check(oldBody[i].LevelDataSha256 == OldBodies[i] && newBody[i].LevelDataSha256 == NewBodies[i],
                "Both independent old and new complete raw-body goldens stay fixed.");
            Check(newStage[i].UpstreamPlanSha256 == texture[i].PlanSha256 &&
                newStage[i].PairedUploadSha256 == texture[i].UploadSha256 &&
                newBody[i].UpstreamPlanSha256 == texture[i].PlanSha256 &&
                newBody[i].StagingPlanSha256 == newStage[i].PlanSha256,
                "Complete private texture plan and actual upload revision flow through the same staging/body ownership chain.");
            Check(newStage[i].TransferSourceSha256 == Transfer && oldStage[i].TransferSourceSha256 == Transfer &&
                newStage[i].CopyTransferSourceImage().SequenceEqual(oldStage[i].CopyTransferSourceImage()) &&
                newStage[i].PairedUploadSha256 != oldStage[i].PairedUploadSha256 &&
                newStage[i].PlanSha256 != oldStage[i].PlanSha256,
                "Equal transfer bytes are a deliberate adversarial fixture, not permission to exchange different full uploads.");
            Check(newStage[i].SourceReads.SequenceEqual(oldStage[i].SourceReads) &&
                newStage[i].Owners.SequenceEqual(oldStage[i].Owners),
                "Complete ordered CPU/DMA source reads and transfer owners remain identical when all transfer bytes and offsets are unchanged.");
            NativeId65EngineEvidence[] textureEvidence = texture[i].Evidence.Select(e =>
                new NativeId65EngineEvidence(e.Id, "EXE", e.ExecutableFileOffset, e.ByteLength, e.Sha256)).ToArray();
            Check(textureEvidence.Length == 6 && newStage[i].Evidence.SequenceEqual(
                oldStage[i].Evidence.Concat(fresh[i].Evidence).Concat(textureEvidence)),
                "New staging retains the complete actual source-stage prefix, exact fresh ancestor and all six directly converted texture consumers in order.");
            Check(newBody[i].Evidence.SequenceEqual(oldBody[i].Evidence
                .Take(oldBody[i].Evidence.Count-oldStage[i].Evidence.Count).Concat(textureEvidence).Concat(newStage[i].Evidence)),
                "New body retains its complete actual body-source/fresh prefix, all six texture consumers and its own correctly paired staging evidence without omissions.");
            VerifyBody(oldBody[i], newBody[i], texture[i]);
            PendingOnly(newStage[i], newBody[i], texture[i]);
        }
        Check(oldStage[0].PlanSha256 == OldStagingPlan && oldBody[0].PlanSha256 == OldBodyPlan,
            "Adding instance profile must not alter legacy anonymous serialization, evidence order, owners or pending strings.");
        Check(texture[0].UploadSha256 == texture[1].UploadSha256 && texture[0].DataSha256 == texture[1].DataSha256 &&
            texture[0].SceneSha256 != texture[1].SceneSha256 && texture[0].PlanSha256 != texture[1].PlanSha256 &&
            newStage[0].TransferSourceSha256 == newStage[1].TransferSourceSha256 &&
            newStage[0].PlanSha256 != newStage[1].PlanSha256,
            "Two complete genuine scene intents have equal upload/transfer bytes but different private revision identities.");
        const string unopened = "textured-body-cross-pair-must-not-open.bin";
        for (int i = 0; i < 2; i++)
        {
            int index = i;
            Reject(() => NativeId65NormalBodyPlan.CaptureTexturedAsync(unopened, texture[index], oldStage[index]).GetAwaiter().GetResult(),
                "Old stage/new texture refuses before source I/O even though complete transfer images match.");
            Reject(() => NativeId65NormalBodyPlan.CaptureAsync(unopened, fresh[index], newStage[index]).GetAwaiter().GetResult(),
                "New stage/old fresh refuses before source I/O; the old overload remains unchanged.");
            Reject(() => NativeId65NormalBodyPlan.CaptureTexturedAsync(unopened, texture[index], newStage[1-index]).GetAwaiter().GetResult(),
                "Equal-upload/transfer different-scene textured revisions refuse before source I/O.");
            Reject(() => NativeId65NormalBodyPlan.CaptureAsync(unopened, fresh[index], oldStage[1-index]).GetAwaiter().GetResult(),
                "Existing equal-upload/different-scene untextured refusal remains intact.");
            Reject(() => NativeId65FreshDiscPlan.CaptureAsync(unopened, newBody[index], 19).GetAwaiter().GetResult(),
                "Existing untextured disc issuer refuses textured instance profile/used end despite identical full CD body length.");
        }
        string wrongSource = typeof(NativeId65NormalBodyPlan).Assembly.Location;
        Reject(() => NativeId65NormalUploadStaging.CaptureTexturedAsync(wrongSource, texture[0]).GetAwaiter().GetResult(),
            "A real wrong-length source file cannot issue a valid texture staging capture.");
        Reject(() => NativeId65NormalBodyPlan.CaptureTexturedAsync(wrongSource, texture[0], newStage[0]).GetAwaiter().GetResult(),
            "A real wrong-length source file cannot issue a valid body from otherwise valid private paired inputs.");
        using var cancelled = new CancellationTokenSource(); cancelled.Cancel();
        await Cancelled(() => NativeId65NormalUploadStaging.CaptureTexturedAsync(path, texture[0], cancelled.Token));
        await Cancelled(() => NativeId65NormalBodyPlan.CaptureTexturedAsync(path, texture[0], newStage[0], cancelled.Token));
        var stageAgain = await NativeId65NormalUploadStaging.CaptureTexturedAsync(path, texture[0]);
        var bodyAgain = await NativeId65NormalBodyPlan.CaptureTexturedAsync(path, texture[0], stageAgain);
        Check(stageAgain.PlanSha256 == newStage[0].PlanSha256 && bodyAgain.PlanSha256 == newBody[0].PlanSha256 &&
            bodyAgain.CopyLevelData().SequenceEqual(newBody[0].CopyLevelData()), "Genuine retry is deterministic after all failed cross-pairs.");
        for (int i = 0; i < 2; i++)
            Check(fresh[i].CopyScene().SequenceEqual(oldScene[i]) && fresh[i].CopyUploadPayload().SequenceEqual(oldUpload[i]) &&
                fresh[i].CopyDataComponents().SequenceEqual(oldData[i]) && fresh[i].CopyModelPayload().SequenceEqual(oldModel[i]),
                "Every original issued upstream byte domain remains unchanged.");
        RequireOriginal(path);
        Console.WriteLine($"TEXTURED_BODY first={newBody[0].LevelDataSha256} second={newBody[1].LevelDataSha256} " +
            $"oldStagePlan={oldStage[0].PlanSha256} oldBodyPlan={oldBody[0].PlanSha256} transfer={newStage[0].TransferSourceSha256}");
    }

    private static void VerifyBody(NativeId65NormalBodyPlan old, NativeId65NormalBodyPlan plan,
        NativeId65FreshTerrainTexturePlan texture)
    {
        byte[] previous = old.CopyLevelData(), actual = plan.CopyLevelData(), expected = previous.ToArray();
        byte[] upload = texture.CopyUploadPayload(), data = texture.CopyDataComponents(), overlay = old.CopyEngineOverlay();
        upload.CopyTo(expected, 0x800);
        expected.AsSpan(0xDE800, 0x1000).Clear(); data.CopyTo(expected, 0xDE800);
        Check(actual.SequenceEqual(expected) && actual.AsSpan(0, 0x800).SequenceEqual(previous.AsSpan(0, 0x800)) &&
            actual.AsSpan(0xDF800).SequenceEqual(previous.AsSpan(0xDF800)) &&
            plan.CopyEngineOverlay().SequenceEqual(overlay),
            "Whole upload/data replacement only: full header, model, scene, four auxiliaries and native engine complement remain exact.");
        Check(plan.DataUsedByteLength == 0xA38 && old.DataUsedByteLength == 0x8C8 &&
            plan.DataSectorByteLength == old.DataSectorByteLength && plan.DataSectorByteLength == 0x1000 &&
            actual.AsSpan(0xDF238, 0x5C8).ToArray().All(b => b == 0),
            "Used data grows0x170 while actual sector allocation stays1000; new5C8 padding is not native used storage.");
        Check(plan.CopyBufferAddress == old.CopyBufferAddress && plan.CopyBufferAddress == 0x80089ECC &&
            plan.ModelRuntimeAddress == 0x8008A904 && plan.SceneRuntimeAddress == 0x8009A104 &&
            plan.KnownSceneEndAddress == 0x8009D104 && plan.ModelRuntimeAddress-old.ModelRuntimeAddress == 0x170 &&
            plan.SceneRuntimeAddress-old.SceneRuntimeAddress == 0x170 && plan.KnownSceneEndAddress-old.KnownSceneEndAddress == 0x170,
            "Native loader used-end arithmetic moves model, scene and known dynamic scene arena together by170, not zero or one CD sector.");
        Check(plan.PhaseOverlaps.Count == 2 && plan.PhaseOverlaps[0] == old.PhaseOverlaps[0] &&
            plan.PhaseOverlaps[1].RuntimeAddress == plan.ModelRuntimeAddress && plan.PhaseOverlaps[1].ByteLength == 0x5C8,
            "Source phase-overwrite evidence derives actual new data-padding overlap without changing source overlay lifetime claim.");
        Check(plan.ReadPhases.Count == old.ReadPhases.Count &&
            plan.ReadPhases.Select(p => p.Id).SequenceEqual(old.ReadPhases.Select(p => p.Id)),
            "The entire ordered native read-phase inventory is retained; an omitted or duplicated phase cannot pass per-phase comparisons.");
        foreach (var read in plan.ReadPhases)
        {
            var prior = old.ReadPhases.Single(p => p.Id == read.Id);
            Check(read.ByteLength == prior.ByteLength && read.NativeOperation == prior.NativeOperation &&
                read.RequiresExternalCompletion == prior.RequiresExternalCompletion &&
                read.RuntimeAddress == prior.RuntimeAddress + (read.Id is "model-read" or "scene-read" ? 0x170u : 0u),
                "Only source-derived model/scene request addresses change; all completion obligations and actual CD lengths remain.");
        }
        Check(plan.Descriptors.SequenceEqual(old.Descriptors) && plan.ModelRoots.SequenceEqual(old.ModelRoots) &&
            plan.AuxiliaryOwners.SequenceEqual(old.AuxiliaryOwners) && plan.Callbacks.SequenceEqual(old.Callbacks),
            "Both CD headers, full root0/companion registrations, auxiliary owners and callbacks retain exact unchanged ownership.");
        int cursor = 0;
        foreach (var owner in plan.Owners)
        {
            Check(owner.Offset == cursor && owner.ByteLength > 0 && Hash(actual.AsSpan(owner.Offset, owner.ByteLength)) == owner.Sha256,
                "All body output owners form a complete byte-exact partition, including changed used end and padding.");
            cursor += owner.ByteLength;
        }
        Check(cursor == actual.Length && BinaryPrimitives.ReadInt32LittleEndian(actual.AsSpan(0xDE800)) == 0x178 &&
            BinaryPrimitives.ReadInt32LittleEndian(actual.AsSpan(0xDEA08)) == 0 &&
            BinaryPrimitives.ReadInt32LittleEndian(actual.AsSpan(0xDEA18)) == 1,
            "Full body retains native two-material metadata and the actual two face IDs.");
        plan.RequireExactPayloads(actual, overlay);
        foreach (int at in new[] { 0, 0x50, 0x152, 0x800, 0x80000, 0x80800, 0xDE800, 0xDEA08, 0xDEA18,
            0xDF237, 0xDF238, 0xDF7FF, 0xDF800, 0xEF000, 0xF2000, actual.Length-1 })
        {
            byte[] bad = actual.ToArray(); bad[at] ^= 1;
            Reject(() => plan.RequireExactPayloads(bad, overlay), "Changed header/upload/data/face/padding/model/scene/auxiliary byte refuses complete readback.");
        }
        foreach (int at in new[] { 0, 0xF494, overlay.Length-1 })
        {
            byte[] bad = overlay.ToArray(); bad[at] ^= 1;
            Reject(() => plan.RequireExactPayloads(actual, bad), "Native engine exact complement remains protected.");
        }
        Reject(() => plan.RequireExactPayloads(actual[..^1], overlay), "Truncated body refuses.");
        Reject(() => plan.RequireExactPayloads(actual.Concat(new byte[1]).ToArray(), overlay), "Foreign body suffix refuses.");
        byte[] exposed = plan.CopyLevelData(); exposed[0] ^= 1;
        Check(plan.CopyLevelData().SequenceEqual(actual), "Returned body buffers do not mutate the accepted private revision.");
    }

    private static void PendingOnly(NativeId65NormalUploadStaging staging, NativeId65NormalBodyPlan body,
        NativeId65FreshTerrainTexturePlan texture)
    {
        Check(texture.NativeClip == 0x8000 && texture.AdditionalPacketBytesPerPass == 24 && !texture.HqRuntimeProven &&
            !texture.RuntimeVerified && !texture.PublicationApproved && !texture.CompleteLevelResourcesProven,
            "Fixed direct-LQ/default-clip record ownership remains conditional; packet-per-pass delta is not a whole-frame or HQ proof.");
        Check(staging.SourceCertified && !staging.CompleteSpuStateProven && !staging.HardwareTransfersProven &&
            !staging.TransferTimingProven && !staging.PeakRuntimeMemoryProven && !staging.SpuWrapSemanticsProven &&
            !staging.CompleteLevelResourcesProven && !staging.IndependentLevelSupported && !staging.RuntimeVerified && !staging.PublicationApproved,
            "Textured transfer composition does not promote any hardware, peak, runtime or publication gate.");
        Check(body.SourceCertified && !body.CallbacksInstalled && !body.CompleteNativeDependencyClosureProven &&
            !body.CompleteLevelResourcesProven && !body.IndependentLevelSupported && !body.PublicationApproved &&
            !body.RuntimeVerified && !body.PeakRuntimeMemoryProven && !body.TransferTimingProven &&
            !body.SpuWrapSemanticsProven && !body.RescueReplayRuntimeProven && !body.CheckpointOrForeignStateSupported,
            "Detached body remains outside complete native, foreign-state, runtime and publication acceptance.");
    }

    private static async Task Cancelled<T>(Func<Task<T>> action)
    {
        bool cancelled = false;
        try { await action(); } catch (OperationCanceledException) { cancelled = true; }
        Check(cancelled, "Cancellation cannot return a partly accepted new revision.");
    }

    private static void RequireOriginal(string path)
    {
        using var input = File.OpenRead(path);
        Check(input.Length == 661547040, "Original source length remains exact.");
        Check(Convert.ToHexStringLower(SHA256.HashData(input)) == Original && input.Position == input.Length &&
            input.Length == 661547040, "Original source complete identity is unchanged before/after every new test path.");
    }
}
